  "dimensions": [
    {
      "dimensionId": "pacingExecution",
      "assertions": [
        {
          "text": "本次骑行总距离 56 公里，移动时长 2 小时 9 分钟，总用时 2 小时 20 分钟，途中停车 10 次。",
