          ]
        },
        {
          "text": "平均速度 26.1 km/h，速度变异系数 37.6%，速度波动较大。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:speed.mean",
