            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:segment.cruise.cruise-1-3117.cadence.mean"
          ]
        },
        {
          "text": "地形分布上，爬坡段累计 24.7 公里，平路 12.7 公里，下坡 18.3 公里，地形以爬坡为主。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:terrain.trendClimbDistanceM",
