          ]
        }
      ]
    },
    {
      "dimensionId": "powerOutput",
      "assertions": [
        {
          "text": "平均功率 159W，归一化功率 218W，平均功率体重比 2.27 W/kg，强度因子 1.09，训练压力指数 253.3。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:power.mean",
