            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.mean",
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.coefficientOfVariation"
