          ]
        },
        {
          "text": "踏频数据部分缺失，整体踏频水平仅供参考。",
          "conclusionType": "fact",
          "claimIds": [
            "claim:upload-965aa12e-01a1-4aaf-84bc-66395c9e92eb:v2:cadence.mean"
          ]
        }
      ]
    },
    {
      "dimensionId": "crossSensorCoordination",
      "assertions": [
        {
          "text": "功率-速度同窗覆盖率为 100%，功率-踏频同窗覆盖率为 96%，传感器数据对齐良好。",
